"""Create a compact 4-slide project milestone deck without external packages."""
from zipfile import ZipFile, ZIP_DEFLATED
from pathlib import Path
from xml.sax.saxutils import escape

OUT = Path("results/Graph_TIGER_project_update.pptx")
NS = "http://schemas.openxmlformats.org/presentationml/2006/main"
RNS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
DRAW = "http://schemas.openxmlformats.org/drawingml/2006/main"

def tx(x, y, w, h, text, size=22, color="FFFFFF", bold=False):
    runs = "".join(f'<a:r><a:rPr lang="en-US" sz="{size*100}" b="{str(bold).lower()}"><a:solidFill><a:srgbClr val="{color}"/></a:solidFill></a:rPr><a:t>{escape(line)}</a:t></a:r><a:br/>' for line in text.split("\n"))
    return f'''<p:sp><p:nvSpPr><p:cNvPr id="{x}{y}" name="Text"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{w}" cy="{h}"/></a:xfrm></p:spPr><p:txBody><a:bodyPr/><a:lstStyle/><a:p>{runs}</a:p></p:txBody></p:sp>'''

def box(x, y, w, h, text, fill="203864", size=20):
    return f'''<p:sp><p:nvSpPr><p:cNvPr id="{x+y}" name="Box"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x="{x}" y="{y}"/><a:ext cx="{w}" cy="{h}"/></a:xfrm><a:prstGeom prst="roundRect"><a:avLst/></a:prstGeom><a:solidFill><a:srgbClr val="{fill}"/></a:solidFill><a:ln><a:solidFill><a:srgbClr val="66CCFF"/></a:solidFill></a:ln></p:spPr><p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang="en-US" sz="{size*100}" b="true"><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill></a:rPr><a:t>{escape(text)}</a:t></a:r></p></p:txBody></p:sp>'''

def slide(title, body):
    return f'''<p:sld xmlns:a="{DRAW}" xmlns:r="{RNS}" xmlns:p="{NS}"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id="2" name="Title"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr/><p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang="en-US" sz="3000" b="true"><a:solidFill><a:srgbClr val="66CCFF"/></a:solidFill></a:rPr><a:t>{escape(title)}</a:t></a:r></a:p></p:txBody></p:sp>{body}</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>'''

def make():
    slides = []
    slides.append(slide("Graph-TIGER: Project Update", tx(700000, 1500000, 11000000, 4000000, "Goal\nTest whether user–item graph information improves a TIGER-style generative recommender on Amazon Beauty.\n\nTeam milestone: data pipeline, baselines, content-aware prototype, and Hazel GPU workflow completed.", 2300)))
    slides.append(slide("Completed Work and Results", tx(700000, 1400000, 11000000, 5600000, "Dataset: 786,049 interactions | 147,241 users | 163,257 items\nChronological split: 491,567 train / 147,241 validation / 147,241 test\n\nPopularity baseline: Recall@10 = 0.0080\nContent-aware raw-ID prototype, epoch 63: Recall@10 = 0.01304; NDCG@10 = 0.00699\n\nConclusion: learned content-aware sequential modeling beats popularity, but this is not yet full semantic-ID TIGER.", 1900)))
    arch = box(600000, 1700000, 2600000, 900000, "User history", "203864") + box(3800000, 1700000, 2800000, 900000, "Raw item IDs", "7F6000") + box(7300000, 1700000, 3000000, 900000, "Transformer", "7030A0") + box(10300000, 1700000, 1800000, 900000, "Next item", "C00000")
    arch += tx(800000, 3100000, 10500000, 2500000, "Current architecture\nHistory → raw item-token embeddings + 64-D content embedding → Transformer → 163K-way item classifier\n\nLimitation: generated semantic IDs are not yet the prediction target.", 1800)
    slides.append(slide("Architecture: Current Prototype", arch))
    arch2 = box(400000, 1500000, 2200000, 900000, "User history", "203864") + box(3000000, 1000000, 2400000, 900000, "Semantic-ID\nsequence", "7F6000") + box(3000000, 2300000, 2400000, 900000, "LightGCN\nembeddings", "008080") + box(6200000, 1600000, 2500000, 1100000, "TIGER\nTransformer", "7030A0") + box(9500000, 1600000, 2200000, 1100000, "Semantic-ID\ndecoder", "C00000")
    arch2 += tx(600000, 3500000, 11000000, 2600000, "Next steps\n1. Predict semantic-ID code components instead of raw item IDs.\n2. Decode codewords back to candidate products.\n3. Fuse LightGCN collaborative embeddings with content embeddings.\n4. Compare popularity, raw-ID, content-aware, semantic-ID TIGER, and graph-enhanced TIGER.", 1800)
    slides.append(slide("Planned Architecture and Research Test", arch2))

    files = {
        "[Content_Types].xml": '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/><Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/><Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/><Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>' + ''.join(f'<Override PartName="/ppt/slides/slide{i}.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>' for i in range(1,5)) + '</Types>',
        "_rels/.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/></Relationships>',
        "ppt/presentation.xml": f'<p:presentation xmlns:a="{DRAW}" xmlns:r="{RNS}" xmlns:p="{NS}"><p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId5"/></p:sldMasterIdLst><p:sldIdLst>' + ''.join(f'<p:sldId id="{255+i}" r:id="rId{i}"/>' for i in range(1,5)) + '</p:sldIdLst><p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>',
        "ppt/_rels/presentation.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' + ''.join(f'<Relationship Id="rId{i}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide{i}.xml"/>' for i in range(1,5)) + '<Relationship Id="rId5" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/></Relationships>',
        "ppt/slideMasters/slideMaster1.xml": f'<p:sldMaster xmlns:a="{DRAW}" xmlns:r="{RNS}" xmlns:p="{NS}"><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/></p:spTree></p:cSld><p:sldLayoutIdLst><p:sldLayoutId id="1" r:id="rId1"/></p:sldLayoutIdLst><p:txStyles/><p:clrMap accent1="66CCFF" accent2="203864" accent3="7F6000" accent4="7030A0" accent5="008080" accent6="C00000" bg1="FFFFFF" bg2="FFFFFF" folHlink="0000FF" hlink="0000FF" tx1="000000" tx2="000000"/></p:sldMaster>',
        "ppt/slideMasters/_rels/slideMaster1.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="../theme/theme1.xml"/></Relationships>',
        "ppt/slideLayouts/slideLayout1.xml": f'<p:sldLayout xmlns:a="{DRAW}" xmlns:r="{RNS}" xmlns:p="{NS}" type="blank"><p:cSld name="Blank"><p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/></p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>',
        "ppt/slideLayouts/_rels/slideLayout1.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="../slideMasters/slideMaster1.xml"/></Relationships>',
        "ppt/theme/theme1.xml": '<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="GraphTIGER"><a:themeElements><a:clrScheme name="GraphTIGER"><a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1><a:lt1><a:sysClr val="window" lastClr="FFFFFF"/></a:lt1><a:dk2><a:srgbClr val="203864"/></a:dk2><a:lt2><a:srgbClr val="FFFFFF"/></a:lt2><a:accent1><a:srgbClr val="66CCFF"/></a:accent1><a:accent2><a:srgbClr val="7F6000"/></a:accent2><a:accent3><a:srgbClr val="7030A0"/></a:accent3><a:accent4><a:srgbClr val="008080"/></a:accent4><a:accent5><a:srgbClr val="C00000"/></a:accent5><a:accent6><a:srgbClr val="FFFFFF"/></a:accent6><a:hlink><a:srgbClr val="0000FF"/></a:hlink><a:folHlink><a:srgbClr val="800080"/></a:folHlink></a:clrScheme><a:fontScheme name="GraphTIGER"><a:majorFont><a:latin typeface="Arial"/></a:majorFont><a:minorFont><a:latin typeface="Arial"/></a:minorFont></a:fontScheme><a:fmtScheme name="GraphTIGER"><a:fillStyleLst/><a:lnStyleLst/><a:effectStyleLst/><a:bgFillStyleLst/></a:fmtScheme></a:themeElements></a:theme>',
        "ppt/slides/_rels/slide1.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>',
        "ppt/slides/_rels/slide2.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>',
        "ppt/slides/_rels/slide3.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>',
        "ppt/slides/_rels/slide4.xml.rels": '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>'
    }
    for i, s in enumerate(slides, 1): files[f"ppt/slides/slide{i}.xml"] = s
    OUT.parent.mkdir(exist_ok=True)
    with ZipFile(OUT, "w", ZIP_DEFLATED) as z:
        for name, data in files.items(): z.writestr(name, data)
    print(OUT)

if __name__ == "__main__": make()
